<script setup lang="ts">
import { ref } from "vue";
import { http } from "@/utils/http";
type Notification = Record<string, any>; const tab = ref("center"); const scope = ref("mine"); const rows = ref<Notification[]>([]); const loading = ref(false); const error = ref("");
async function load() { loading.value = true; try { const result = await http.get<unknown, unknown>("/communications/notifications"); rows.value = Array.isArray(result) ? result as Notification[] : []; } catch (e: any) { error.value = e?.response?.data?.detail || "通知接口尚未接入"; } finally { loading.value = false; } }
load();
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">通知中心与投递</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">查看授权范围内通知，并管理安全投递策略。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="warning" show-icon :closable="false" class="mb-4"/><el-tabs v-model="tab"><el-tab-pane label="通知中心" name="center"/><el-tab-pane label="投递规则" name="rules"/><el-tab-pane label="投递日志" name="logs"/></el-tabs><el-card shadow="never" class="mt-4"><template v-if="tab === 'center'"><div class="flex gap-3 mb-4"><el-radio-group v-model="scope"><el-radio-button label="mine">我的</el-radio-button><el-radio-button label="authorized">全部授权范围</el-radio-button></el-radio-group><el-select placeholder="阅读状态"><el-option label="全部" value="all"/><el-option label="未读" value="unread"/><el-option label="已读" value="read"/></el-select></div><el-empty v-if="!rows.length" description="暂无通知"/><el-table v-else :data="rows" stripe><el-table-column prop="source" label="来源" width="150"/><el-table-column prop="title" label="标题" min-width="240"/><el-table-column prop="preview" label="正文预览" min-width="260"/><el-table-column prop="priority" label="优先级" width="110"/><el-table-column prop="createdAt" label="创建时间" min-width="180"/><el-table-column prop="status" label="状态" width="110"/></el-table></template><template v-else-if="tab === 'rules'"><el-empty description="暂无投递规则"/><el-button>新增投递规则</el-button></template><template v-else><el-empty description="暂无投递日志"/></template></el-card></main></template>
